 "Moverse": "Se déplacer",
 "<b style=\"font-size:25px;color:#118ab2\">Moverse</b><br><span style=\"font-size:21px;color:#143338\">Paradas, carril bici y aceras anchas.</span>": "<b style=\"font-size:25px;color:#118ab2\">Se déplacer</b><br><span style=\"font-size:21px;color:#143338\">Arrêts, piste cyclable et larges trottoirs.</span>",
